    x = np.random.uniform(lb, ub, size=dim)
    best_x = x.copy()
    for _ in range(budget):
        radius = 0.5
        while True:
            z = x + rng.uniform(-radius, radius, size=dim)
            z = clip(z)
            if func(z) < func(best_x):
